SELECT 
    cv."CHASSIS_ID",
    ROUND(
        (1 - (COALESCE((cv.ground_vehicle_status->'brake_system'->>'pad_wear_pct')::numeric, 0) + COALESCE((cv.ground_vehicle_status->'tracks'->>'wear_pct')::numeric, 0)) / 200
        ) * (COALESCE(REPLACE(cv.ground_vehicle_status->'vehicle_motion'->>'speed_kmh', ' m/s', '')::real, 0) * 3.6 / 50)
        * (COALESCE((e."engine_fluids_snapshot"->'engine_core'->>'load_pct')::numeric, 0) / 100)::numeric,
        4
    ) AS vehicle_performance_score
FROM "ChassisAndVehicle" cv
JOIN "EngineAndFluids" e ON cv.engine_link = e."ENGINE_ID";

